// Currículo de fundamentos: ruta matemática M0–M6, Computer Science CS0–CS7,
// proyectos progresivos y parches pedagógicos sobre los temas existentes.
import type { CareerPath, Resource, Topic, Tier } from "./roadmap-data";

export interface StageMeta {
  id: string;
  track: "math" | "cs" | "projects";
  title: string;
  goal: string;
  advanceWhen: string; // criterio objetivo para avanzar
  estimate: string; // rango, depende del nivel inicial
}

export const STAGES: StageMeta[] = [
  { id: "M0", track: "math", title: "Aritmética y fundamentos numéricos", goal: "Eliminar lagunas numéricas que bloquean todo lo demás.", advanceWhen: "≥ 90% en un set de 20 ejercicios mixtos sin calculadora.", estimate: "0–4 semanas" },
  { id: "M1", track: "math", title: "Álgebra elemental", goal: "Manipular expresiones, ecuaciones y funciones con soltura.", advanceWhen: "Resolver sistemas, factorizar y graficar funciones exp/log sin consultar.", estimate: "2–8 semanas" },
  { id: "M2", track: "math", title: "Matemáticas discretas y lógica", goal: "Razonar con precisión: lógica, demostraciones, conteo, grafos.", advanceWhen: "Escribir demostraciones por inducción y contradicción correctas y resolver problemas de conteo.", estimate: "6–12 semanas" },
  { id: "M3", track: "math", title: "Matemáticas para análisis de algoritmos", goal: "Analizar tiempo, espacio y corrección de algoritmos.", advanceWhen: "Derivar la complejidad de algoritmos iterativos y recursivos, y argumentar corrección con invariantes.", estimate: "3–6 semanas" },
  { id: "M4", track: "math", title: "Probabilidad y estadística", goal: "Modelar incertidumbre y evaluar experimentos.", advanceWhen: "Resolver problemas de Bayes, esperanza y varianza; diseñar un experimento simple.", estimate: "4–10 semanas" },
  { id: "M5", track: "math", title: "Álgebra lineal", goal: "Pensar en vectores, matrices y transformaciones.", advanceWhen: "Resolver sistemas, calcular autovalores y explicar geométricamente qué hace una matriz.", estimate: "4–10 semanas" },
  { id: "M6", track: "math", title: "Cálculo y optimización", goal: "Derivadas, gradientes y descenso por gradiente.", advanceWhen: "Calcular gradientes con regla de la cadena e implementar descenso por gradiente desde cero.", estimate: "4–10 semanas" },
  { id: "CS0", track: "cs", title: "Pensamiento computacional", goal: "Descomponer problemas y diseñar algoritmos antes de programar.", advanceWhen: "Escribir pseudocódigo correcto con casos límite para 5 problemas nuevos.", estimate: "1–3 semanas" },
  { id: "CS1", track: "cs", title: "Fundamentos de programación", goal: "Programar con soltura en un lenguaje, probar y depurar.", advanceWhen: "Resolver 30+ ejercicios con tests, y leer/modificar código ajeno.", estimate: "6–12 semanas" },
  { id: "CS2", track: "cs", title: "Programación en profundidad", goal: "Entender qué pasa al ejecutar: memoria, referencias, tipos, concurrencia.", advanceWhen: "Explicar stack/heap, aliasing y mutabilidad con ejemplos propios; perfilar un programa.", estimate: "4–8 semanas" },
  { id: "CS3", track: "cs", title: "Estructuras de datos y algoritmos", goal: "Implementar y analizar las estructuras y técnicas clásicas.", advanceWhen: "Implementar cada estructura con tests y resolver problemas nuevos de cada técnica.", estimate: "10–20 semanas" },
  { id: "CS4", track: "cs", title: "Arquitectura de computadores", goal: "Del bit a la CPU: representación y jerarquía de memoria.", advanceWhen: "Convertir entre bases, explicar complemento a dos, float y el efecto de la caché.", estimate: "4–8 semanas" },
  { id: "CS5", track: "cs", title: "Sistemas operativos", goal: "Procesos, memoria virtual, concurrencia y archivos.", advanceWhen: "Explicar y reproducir una race condition y un deadlock, y corregirlos.", estimate: "6–12 semanas" },
  { id: "CS6", track: "cs", title: "Redes", goal: "Cómo viajan los datos y qué falla en el camino.", advanceWhen: "Trazar una petición HTTPS de punta a punta y escribir un cliente/servidor con sockets.", estimate: "4–8 semanas" },
  { id: "CS7", track: "cs", title: "Paradigmas y fundamentos avanzados", goal: "Tipos, compiladores, computabilidad, criptografía (recomendado/opcional).", advanceWhen: "Según el tema; ninguno bloquea la ruta principal.", estimate: "Variable" },
  { id: "P1", track: "projects", title: "Proyectos de fundamentos", goal: "Demostrar dominio de estructuras y algoritmos.", advanceWhen: "Repo con tests, benchmarks y README que explique complejidades.", estimate: "2–6 semanas" },
  { id: "P2", track: "projects", title: "Proyectos de sistemas", goal: "Demostrar comprensión de SO, redes y almacenamiento.", advanceWhen: "El sistema soporta pruebas de carga y fallos documentados.", estimate: "3–8 semanas" },
  { id: "P3", track: "projects", title: "Proyectos de backend", goal: "Transacciones, concurrencia, asincronía y observabilidad.", advanceWhen: "Pruebas de concurrencia e idempotencia pasan; métricas visibles.", estimate: "3–8 semanas" },
  { id: "P4", track: "projects", title: "Proyectos de AI Engineering", goal: "Sistemas de IA evaluados, seguros y observables.", advanceWhen: "Existe un set de evaluación versionado con métricas reportadas.", estimate: "3–8 semanas" },
];

export const STAGE_BY_ID: Record<string, StageMeta> = Object.fromEntries(STAGES.map((s) => [s.id, s]));

